    "desc": "仕事以外の要因は、職場環境の評価・改善、個々の労働者への配慮、ストレスチェック制度に関わる用語です。まず「仕事以外の要因も含めて把握することが重要」という出題上のポイントと結びつけて理解します。過去問・演習では「NIOSHモデルでは仕事のストレス要因に加え、個人的要因・緩衝要因（上司・同僚・家族の支援など）がストレス反応を修飾し、最終的な健康障害に至るプロセスを示している」という形で扱われるため、単語だけでなく設問の場面も確認します。ラインケアの視点では、職場要因を把握し、業務量・裁量・支援体制など改善できる点へつなげることが重要です。関連する用語として、ストレス、ストレス反応、仕事のストレス要因、個人的要因もあわせて確認すると理解がつながります。\n\n試験では、仕事以外の要因の定義を丸暗記するだけでなく、職場環境・配慮の中でどの場面に出るかを問われます。タグ上は「第4章 / 注意すべきストレス要因とその予防 / 第2章」と関連するため、章・テーマ名とセットで覚えると選択肢を絞りやすくなります。確認問題では「仕事以外の要因（家庭など）はモデルの対象外とされている」のような聞かれ方があります。解説では「NIOSHモデルでは仕事のストレス要因に加え、個人的要因・緩衝要因（上司・同僚・家族の支援など）がストレス反応を修飾し、最終的な健康障害に至るプロセスを示している」という整理が使われています。混同しやすい関連語は「ストレス・ストレス反応・仕事のストレス要因・個人的要因」です。違いを一言で説明できる状態にしておきましょう。"
