    "summary": "職場復帰支援プラン作成の際に検討すべき内容は、休業者が無理なく職場へ戻るための手順や配慮を整理する用語です。",
    "desc": "職場復帰支援プラン作成の際に検討すべき内容は、休業開始から復職後のフォローアップまで、本人の状態、主治医の意見、産業医の意見、職場の受け入れ体制を確認するために使われます。復職支援では、病名そのものよりも、勤務時間、業務負荷、配慮事項、再発予防を具体化することが重要です。職場では、用語の意味だけでなく、誰が対応し、どの情報を共有し、どの専門職につなぐかまで確認します。実務では、本人の安心感を保ちつつ、社内外の支援先とどのタイミングで連携するかを意識します。\n\n試験では、主治医の診断書だけで復職が決まる、復職直後から通常勤務に戻す、病名を職場全体で共有する、といった選択肢に注意します。本人同意、必要最小限の情報共有、産業医等との連携を押さえます。試験では、本人同意、必要最小限の情報共有、専門職連携、復職後フォローアップまで一連で押さえます。選択肢では、本人任せにする対応、情報を広く共有する対応、専門職へつながない対応が誤りになりやすいです。"
