    "desc": "過食症では、短時間に大量に食べる過食発作と、嘔吐、下剤使用、絶食、過度な運動などがみられることがあります。外見だけでは気づきにくい場合もあり、本人の苦痛が大きい疾患です。職場では、用語の意味だけでなく、誰が対応し、どの情報を共有し、どの専門職につなぐかまで確認します。実務では、用語を単独で覚えるのではなく、ラインケア・安全配慮・専門職連携の流れに置いて確認します。\n\n試験では、摂食障害を本人の性格や意志だけで説明しないことが重要です。職場では診断ではなく、体調不良、遅刻・欠勤、集中困難などの変化から支援につなげます。試験では、定義の丸暗記よりも、ラインケア・セルフケア・産業保健スタッフ等との役割分担に置いて判断することが重要です。選択肢では、管理監督者が医学的診断をする記述や、本人の性格だけを原因にする記述が誤りになりやすいです。"
